<template>
  <div v-if="visible" class="mobile-tab-container" :style="customStyle">
    <div class="segmented-control">
      <div 
        v-for="tab in tabs" 
        :key="tab.key"
        class="tab-button"
        :class="{ 'active': activeTab === tab.key }"
        @click="handleTabClick(tab.key)"
      >
        <!-- 选中状态的背景按钮 -->
        <div v-if="activeTab === tab.key" class="selected-background"></div>
        
        <!-- Tab标签文字 -->
        <span class="tab-label">{{ tab.label }}</span>
      </div>
      
      <!-- 分隔符 -->
      <div 
        v-for="(tab, index) in tabs.slice(0, -1)" 
        :key="`separator-${index}`"
        class="separator"
        :style="{ left: `${(index + 1) * (100 / tabs.length)}%` }"
      ></div>
    </div>
  </div>
</template>

<script setup>
import { defineProps, defineEmits } from 'vue';

// Props定义
const props = defineProps({
  visible: {
    type: Boolean,
    default: true
  },
  activeTab: {
    type: String,
    default: 'all'
  },
  tabs: {
    type: Array,
    default: () => [
      { key: 'all', label: 'All' },
      { key: 'image', label: 'Image' },
      { key: 'video', label: 'Video' }
    ]
  },
  customStyle: {
    type: Object,
    default: () => ({})
  }
});

// 事件定义
const emit = defineEmits(['tab-change']);

// 点击事件处理
const handleTabClick = (tabKey) => {
  if (props.activeTab !== tabKey) {
    emit('tab-change', tabKey);
  }
};
</script>

