<template>
  <div 
    ref="containerRef"
    class="mobile-infinite-scroll-container"
    :class="[containerClass, { 'empty-content': isEmptyContent && loading }]"
  >
    <!-- 主要内容插槽 -->
    <div ref="slotRef" class="slot-content">
      <slot></slot>
    </div>

    <!-- Vant List 组件 -->
    <van-list
      v-model:loading="internalLoading"
      :finished="finished"
      :error="isError"
      :offset="distance"
      :loading-text="loadingText"
      finished-text=""
      :error-text="t('loadFailed')"
      :immediate-check="immediate"
      @load="onLoadListener"
      @update:error="onErrorUpdate"
    >
      <!-- 自定义重试按钮 -->
      <template #error>
        <div class="error-wrapper">
          <l-img src="/static/images/format-error.png" w="30px" h="30px" />
          <div class="error-text">{{ t('loadFailed') }}</div>
          <van-button 
            type="primary" 
            size="small" 
            @click="handleRetry"
            class="retry-button"
          >
            {{ retryText }}
          </van-button>
        </div>
      </template>
    </van-list>
  </div>
</template>

<script setup>
import { ref, computed, nextTick, onMounted, onUpdated, watch, defineProps } from 'vue';
import { useI18n } from 'vue-i18n';
import { showMessageInfo } from '@/utils/mobile-ui-feedback.js';
import LImg from '@/mobile/components/mobile-l-img.vue';

// 国际化
const { t } = useI18n();

/**
 * 组件事件接口
 */
const emit = defineEmits(['loadMore', 'retry']);

// Props定义 - 保持与 list-more.vue 一致
const props = defineProps({
  loading: {
    type: Boolean,
    default: false,
  },
  finished: {
    type: Boolean,
    default: false,
  },
  error: {
    type: Boolean,
    default: false,
  },
  distance: {
    type: Number,
    default: 0,
  },
  delay: {
    type: Number,
    default: 200,
  },
  immediate: {
    type: Boolean,
    default: true,
  },
  disabled: {
    type: Boolean,
    default: false,
  },
  containerClass: {
    type: String,
    required: true,
    default: "",
  },
  loadingText: {
    type: String,
    default: "loading...",
  },
  finishedText: {
    type: String,
    default: "no more data",
  },
  retryText: {
    type: String,
    default: "retry",
  }
});

// 模板引用
const containerRef = ref();
const slotRef = ref();

// 内部状态
const internalLoading = ref(false);
const isError = ref(false);
const isEmptyContent = ref(true);
const hasShownFinishedMessage = ref(false); // 标记是否已显示过完成提示

// 监听外部 loading 状态变化
watch(() => props.loading, (newVal) => {
  internalLoading.value = newVal;
}, { immediate: true });

// 监听外部错误状态变化
watch(() => props.error, (newVal) => {
  isError.value = newVal;
}, { immediate: true });

// 监听 finished 状态变化
watch(() => props.finished, (newVal) => {
  if (newVal && !hasShownFinishedMessage.value) {
    handleDataLoadFinished();
  }
  // 重置状态：当finished变为false时，重置标记（用于重新加载时）
  if (!newVal) {
    hasShownFinishedMessage.value = false;
  }
});

/**
 * 处理数据加载完成
 * 统计当前数据数量，如果超过20条则显示提示
 */
const handleDataLoadFinished = () => {
  try {
    // 统计slot内容中的数据项数量
    if (slotRef.value) {
      // 查找常见的列表项选择器
      const itemSelectors = [
        '.media-item',       // 媒体项
        '.list-item',        // 通用列表项
        '.item',             // 通用项
        '[data-item]',       // 带data-item属性的元素
        'li',                // li元素
        '.van-cell'          // Vant单元格
      ];
      
      let totalItems = 0;
      
      // 尝试不同的选择器来统计项目数量
      for (const selector of itemSelectors) {
        const items = slotRef.value.querySelectorAll(selector);
        if (items.length > 0) {
          totalItems = items.length;
          break; // 找到项目就停止查找
        }
      }
      
      // 如果没有找到明确的项目，尝试统计直接子元素
      if (totalItems === 0) {
        // 排除加载状态和空状态的元素
        const directChildren = Array.from(slotRef.value.children).filter(child => {
          return !child.classList.contains('loading') && 
                 !child.classList.contains('empty') &&
                 !child.classList.contains('van-list');
        });
        
        // 如果有grid或flex容器，统计其子元素
        const gridContainer = slotRef.value.querySelector('.media-grid, .grid-container, .list-container');
        if (gridContainer) {
          totalItems = gridContainer.children.length;
        } else {
          totalItems = directChildren.length;
        }
      }
      
      console.log('数据加载完成，检测到项目数量:', totalItems);
      
      // 只有当数据超过20条时才显示提示
      if (totalItems >= 20) {
        showMessageInfo(t('noMoreData') || 'No more data');
        hasShownFinishedMessage.value = true;
      }
    }
  } catch (error) {
    console.warn('统计数据项数量时出错:', error);
    // 出错时使用默认行为：不满20条不提示，超过的话还是提示
    // 可以在这里添加保险逻辑，比如检查是否有数据等
  }
};

/**
 * 计算是否禁用滚动加载
 */
const scrollDisabled = computed(
  () => props.loading || props.finished || props.disabled || isError.value
);

/**
 * 检测slot是否有内容
 */
const checkSlotContent = () => {
  if (slotRef.value) {
    const hasContent =
      slotRef.value.children.length > 0 ||
      slotRef.value.textContent?.trim() !== "";
    isEmptyContent.value = !hasContent;
  }
};

/**
 * 处理加载事件
 */
const onLoadListener = () => {
  if (scrollDisabled.value) return;
  
  // 添加延迟以匹配原组件行为
  if (props.delay > 0) {
    setTimeout(() => {
      emit("loadMore");
    }, props.delay);
  } else {
    emit("loadMore");
  }
};

/**
 * 处理错误状态更新
 */
const onErrorUpdate = (error) => {
  isError.value = error;
};

/**
 * 处理重试事件
 */
const handleRetry = () => {
  console.log('Retry button clicked');
  isError.value = false;
  internalLoading.value = false;
  hasShownFinishedMessage.value = false; // 重试时重置提示状态
  emit("retry");
};

/**
 * 滚动到容器顶部
 */
const scrollToTop = async (behavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    containerRef.value.scrollTo({
      top: 0,
      behavior,
    });
  }
};

/**
 * 滚动到容器底部
 */
const scrollToBottom = async (behavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    const container = containerRef.value;
    container.scrollTo({
      top: container.scrollHeight,
      behavior,
    });
  }
};

/**
 * 滚动到指定位置
 */
const scrollTo = async (top, behavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    containerRef.value.scrollTo({ top, behavior });
  }
};

/**
 * 设置获取失败状态
 */
const changeIsFetchSuccess = () => {
  isError.value = true;
  internalLoading.value = false;
};

// 生命周期钩子
onMounted(() => {
  checkSlotContent();
});

onUpdated(() => {
  checkSlotContent();
});

// 暴露组件方法 - 保持与 list-more.vue 一致
defineExpose({
  scrollToTop,
  scrollToBottom,
  scrollTo,
  containerRef,
  changeIsFetchSuccess,
});
</script>

<style lang="scss" scoped>
.mobile-infinite-scroll-container {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  position: relative;

  // 当内容为空且正在加载时，使用flex布局居中
  &.empty-content {
    display: flex;
    flex-direction: column;
  }

  // 隐藏滚动条（移动端通常隐藏）
  &.hide-scrollbar {
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none; /* Internet Explorer 10+ */

    &::-webkit-scrollbar {
      display: none; /* WebKit */
    }
  }
}

.slot-content {
  // 当容器为空内容模式时，slot内容不占空间
  .empty-content & {
    flex-shrink: 0;
  }
}

// 自定义错误状态样式
.error-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 20px;
  gap: 12px;
  min-height: 200px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  
  .error-text {
    font-size: 14px;
    color: #969799;
    text-align: center;
    line-height: 1.5;
  }
  
  .retry-button {
    margin-top: 28px;
    min-width: 80px;
  }
}

// Vant List 组件样式覆盖
:deep(.van-list) {
  .van-list__loading {
    padding: 16px;
    font-size: 14px;
    color: #969799;
    text-align: center;
    
    .van-loading__spinner {
      width: 16px;
      height: 16px;
      margin-right: 8px;
    }
  }
  
  .van-list__finished-text {
    display: none; // 隐藏默认的结束文本
  }
}
</style>
